1	/**
2	 * Shared Portkey gateway client for the eval harness.
3	 *
4	 * All eval scripts call the hosted Portkey gateway (https://api.portkey.ai/v1)
5	 * instead of talking to model providers directly. Routing uses Portkey's
6	 * model-catalog model strings ("@neuralwatt/<model>"), so no provider header
7	 * or upstream credential is needed here — the neuralwatt key lives in the
8	 * Portkey Model Catalog.
9	 *
10	 * Env:
11	 *   PORTKEY_API_KEY        required
12	 *   PORTKEY_BASE_URL       optional, defaults to https://api.portkey.ai/v1
13	 *   PORTKEY_DEFAULT_MODEL  optional, defaults to @neuralwatt/qwen3.5-397b-fast
14	 *   JUDGE_MODEL            optional, defaults to @neuralwatt/kimi-k2.6
15	 */
16	
17	const PORTKEY_API_KEY = process.env.PORTKEY_API_KEY;
18	const PORTKEY_BASE_URL = (
19	  process.env.PORTKEY_BASE_URL ?? "https://api.portkey.ai/v1"
20	).replace(/\/$/, "");
21	
22	export const DEFAULT_MODEL =
23	  process.env.PORTKEY_DEFAULT_MODEL ?? "@neuralwatt/qwen3.5-397b-fast";
24	export const JUDGE_MODEL =
25	  process.env.JUDGE_MODEL ?? "@neuralwatt/kimi-k2.6";
26	
27	export interface ChatOptions {
28	  system: string;
29	  user: string;
30	  model: string;
31	  temperature: number;
32	  /** Omitted / null → no max_tokens sent. */
33	  maxTokens?: number | null;
34	  signal: AbortSignal;
35	}
36	
37	const RETRY_DELAYS_MS = [1_500, 4_000];
38	const MAX_ATTEMPTS = 3;
39	
40	function sleep(ms: number, signal: AbortSignal): Promise<void> {
41	  return new Promise((resolve, reject) => {
42	    const t = setTimeout(resolve, ms);
43	    if (signal.aborted) {
44	      clearTimeout(t);
45	      reject(signal.reason ?? new Error("aborted"));
46	      return;
47	    }
48	    signal.addEventListener(
49	      "abort",
50	      () => {
51	        clearTimeout(t);
52	        reject(signal.reason ?? new Error("aborted"));
53	      },
54	      { once: true },
55	    );
56	  });
57	}
58	
59	async function chatCompletionOnce(
60	  body: Record<string, unknown>,
61	  signal: AbortSignal,
62	): Promise<string> {
63	  if (!PORTKEY_API_KEY) {
64	    throw new Error("PORTKEY_API_KEY is required");
65	  }
66	  const res = await fetch(`${PORTKEY_BASE_URL}/chat/completions`, {
67	    method: "POST",
68	    headers: {
69	      "content-type": "application/json",
70	      "x-portkey-api-key": PORTKEY_API_KEY,
71	    },
72	    body: JSON.stringify(body),
73	    signal,
74	  });
75	  if (!res.ok) {
76	    const text = await res.text();
77	    const err = new Error(`Portkey ${res.status}: ${text.slice(0, 300)}`);
78	    // Attach status so the retry layer can decide without parsing the message.
79	    (err as Error & { status?: number }).status = res.status;
80	    throw err;
81	  }
82	  const json = (await res.json()) as {
83	    choices?: Array<{ message?: { content?: string } }>;
84	  };
85	  const content = json.choices?.[0]?.message?.content;
86	  if (typeof content !== "string") {
87	    throw new Error("Portkey response missing choices[0].message.content");
88	  }
89	  return content;
90	}
91	
92	/**
93	 * Chat-completions call with retry. Network errors and HTTP 5xx / 504 / 408 /
94	 * 429 responses are retried up to {@link MAX_ATTEMPTS} total attempts with a
95	 * short backoff; other 4xx and non-retryable errors propagate immediately.
96	 * The AbortSignal is owned by the caller and is left untouched.
97	 */
98	export async function chatCompletion(opts: ChatOptions): Promise<string> {
99	  const body: Record<string, unknown> = {
100	    model: opts.model,
101	    messages: [
102	      { role: "system", content: opts.system },
103	      { role: "user", content: opts.user },
104	    ],
105	    temperature: opts.temperature,
106	  };
107	  if (opts.maxTokens !== undefined && opts.maxTokens !== null) {
108	    body.max_tokens = opts.maxTokens;
109	  }
110	  let lastErr: Error | null = null;
111	  for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt += 1) {
112	    try {
113	      return await chatCompletionOnce(body, opts.signal);
114	    } catch (err) {
115	      const e = err as Error & { status?: number; name?: string };
116	      lastErr = e;
117	      const isAbort = e.name === "AbortError";
118	      const status = e.status;
119	      const retryableNetwork =
120	        e instanceof TypeError ||
121	        // node fetch surfaces transient failures as system errors
122	        e.name === "FetchError" ||
123	        // undici uses these
124	        e.name === "UndiciError";
125	      const retryableStatus =
126	        typeof status === "number" &&
127	        (status === 504 || status === 408 || status === 429 || status >= 500);
128	      const shouldRetry =
129	        attempt < MAX_ATTEMPTS - 1 &&
130	        !isAbort &&
131	        (retryableNetwork || retryableStatus);
132	      if (!shouldRetry) throw e;
133	      await sleep(RETRY_DELAYS_MS[attempt], opts.signal);
134	    }
135	  }
136	  // Unreachable, but keep TS happy.
137	  throw lastErr ?? new Error("Portkey call failed");
138	}
