1	/**
2	 * Offline eval harness for Twyne's persona feedback / rubric judges.
3	 *
4	 * Reads each line in `evals/dataset.jsonl`, builds the same system + user
5	 * prompts the production actions build via `convex/agentPrompts`, then
6	 * calls the hosted Portkey gateway that `convex/agents.ts` already routes
7	 * through. Writes the model outputs to `evals/runs.json` in the shape
8	 * `ax experiments create --file` accepts.
9	 *
10	 * Usage:
11	 *   PORTKEY_API_KEY=pk-xxx bun run eval
12	 *
13	 * Calls the hosted Portkey gateway; see evals/llm-client.ts.
14	 *
15	 * Read-only w.r.t. the repo otherwise: only writes `evals/runs.json`.
16	 */
17	import { readFileSync, writeFileSync } from "node:fs";
18	import { dirname, resolve } from "node:path";
19	import { fileURLToPath } from "node:url";
20	
21	import {
22	  buildSystemPrompt,
23	  buildUserPrompt,
24	  toAgentPersona,
25	  type AgentPersona,
26	  type AgentRequest,
27	} from "../convex/agentPrompts";
28	import { PERSONAS } from "../src/utils/personas";
29	import { chatCompletion, DEFAULT_MODEL } from "./llm-client";
30	
31	const HERE = dirname(fileURLToPath(import.meta.url));
32	const DATASET_PATH = resolve(HERE, "dataset.jsonl");
33	const RUNS_PATH = resolve(HERE, "runs.json");
34	
35	interface DatasetRow {
36	  case_id: string;
37	  persona: string;
38	  instruction: string;
39	  draftText: string;
40	}
41	
42	interface RunOutput {
43	  // Local stable key (the dataset's case_id). The Arize-assigned example_id is
44	  // resolved at upload time by joining on case_id (see evals/upload-experiment.ts).
45	  case_id: string;
46	  output: string;
47	}
48	
49	function personaOrThrow(id: string): AgentPersona {
50	  const p = PERSONAS.find((x) => x.id === id);
51	  if (!p) {
52	    throw new Error(
53	      `Unknown persona id "${id}" — add it to src/utils/personas.ts`,
54	    );
55	  }
56	  return toAgentPersona(p);
57	}
58	
59	function readDataset(): DatasetRow[] {
60	  const raw = readFileSync(DATASET_PATH, "utf8").trim();
61	  return raw
62	    .split(/\n+/)
63	    .filter(Boolean)
64	    .map((line, i) => {
65	      try {
66	        return JSON.parse(line) as DatasetRow;
67	      } catch (err) {
68	        throw new Error(`Bad JSONL line ${i + 1}: ${(err as Error).message}`);
69	      }
70	    });
71	}
72	
73	async function main(): Promise<void> {
74	  const dataset = readDataset();
75	  console.log(`[twyne:eval] ${dataset.length} examples → ${DEFAULT_MODEL}`);
76	  const runs: RunOutput[] = [];
77	  let failures = 0;
78	  for (const row of dataset) {
79	    const persona = personaOrThrow(row.persona);
80	    const req: AgentRequest = {
81	      persona,
82	      brief: null,
83	      draftText: row.draftText,
84	      instruction: row.instruction as AgentRequest["instruction"],
85	    };
86	    const system = buildSystemPrompt(persona);
87	    const user = buildUserPrompt(req);
88	    try {
89	      const output = await chatCompletion({
90	        system,
91	        user,
92	        model: DEFAULT_MODEL,
93	        temperature: 0.4,
94	        signal: AbortSignal.timeout(60_000),
95	      });
96	      runs.push({ case_id: row.case_id, output });
97	      console.log(`  ✓ ${row.case_id} (${output.length} chars)`);
98	    } catch (err) {
99	      failures += 1;
100	      const message = (err as Error).message;
101	      runs.push({
102	        case_id: row.case_id,
103	        output: `[error] ${message}`,
104	      });
105	      console.error(`  ✗ ${row.case_id}: ${message}`);
106	    }
107	  }
108	  writeFileSync(RUNS_PATH, JSON.stringify(runs, null, 2));
109	  console.log(
110	    `[twyne:eval] wrote ${runs.length} runs (${failures} failed) to evals/runs.json`,
111	  );
112	  if (failures > 0) {
113	    process.exitCode = 1;
114	  }
115	}
116	
117	main().catch((err) => {
118	  console.error("[twyne:eval] fatal:", err);
119	  process.exit(1);
120	});
