1	/**
2	 * The quote tool the editorial personas call to pin a note to an exact
3	 * passage from the draft.
4	 *
5	 * Instead of asking the model to retype a passage (which it paraphrases,
6	 * truncates, or invents), we hand it a `quote_passage` tool: it passes the
7	 * sentence it is responding to, and the tool fuzzy-resolves that against the
8	 * actual draft and returns the *canonical* verbatim text. The resolved
9	 * passage is captured as the note's anchor, so the anchor always comes from
10	 * the draft itself rather than from the model's typing.
11	 *
12	 * Shared by both code paths:
13	 *  - the client BYOK path in `src/utils/ai-client.ts`
14	 *  - the Convex server path in `convex/agents.ts`
15	 *
16	 * Intentionally no `"use node";` directive and no zod dependency: this is
17	 * pure string assembly plus the AI SDK's `tool`/`jsonSchema` helpers, so it
18	 * bundles cleanly in the Vite client too.
19	 */
20	import { tool, jsonSchema, type ToolSet } from "ai";
21	
22	/* ── Draft passage resolution (verbatim + fuzzy match) ──────────── */
23	
24	/**
25	 * Resolve a (possibly approximate) quote against the draft, returning the
26	 * exact text as it appears in the draft, or undefined when it cannot be
27	 * matched. Used to be `persona-anchors.extractDynamicFeedbackAnchor`'s
28	 * inner matcher; now the single source of truth for both anchoring and the
29	 * quote tool.
30	 */
31	export function resolveDraftPassage(
32	  quote: string | undefined,
33	  draftText: string,
34	): string | undefined {
35	  const cleaned = quote?.replace(/\s+/g, " ").trim();
36	  if (!cleaned || cleaned.split(/\s+/).length < 3) return undefined;
37	  if (draftText.includes(cleaned)) return cleaned;
38	
39	  const normalizedQuote = normalizeText(cleaned);
40	  if (!normalizedQuote) return undefined;
41	
42	  for (const passage of draftPassages(draftText)) {
43	    const normalizedPassage = normalizeText(passage);
44	    if (
45	      normalizedPassage === normalizedQuote ||
46	      normalizedPassage.includes(normalizedQuote)
47	    ) {
48	      return passage;
49	    }
50	  }
51	  return undefined;
52	}
53	
54	/** Split a draft into candidate passages: each sentence and each paragraph. */
55	export function draftPassages(draftText: string): string[] {
56	  const passages: string[] = [];
57	  for (const paragraph of draftText.split(/\n+/)) {
58	    const trimmed = paragraph.trim();
59	    if (!trimmed) continue;
60	    const sentences = trimmed.match(/[^.!?]+[.!?]+(?=\s|$)/g) ?? [];
61	    passages.push(...sentences.map((s) => s.trim()));
62	    passages.push(trimmed);
63	  }
64	  return passages;
65	}
66	
67	export function normalizeText(text: string): string {
68	  return text
69	    .toLowerCase()
70	    .replace(/[“”]/g, '"')
71	    .replace(/[‘’]/g, "'")
72	    .replace(/[^a-z0-9'" ]+/g, " ")
73	    .replace(/\s+/g, " ")
74	    .trim();
75	}
76	
77	/**
78	 * The first substantive sentence of a draft — a deterministic anchor for the
79	 * local fallback generator, which has no model and so cannot call the tool.
80	 */
81	export function firstSubstantiveSentence(draftText: string): string | undefined {
82	  for (const passage of draftPassages(draftText)) {
83	    if (passage.split(/\s+/).length >= 4) return passage;
84	  }
85	  return undefined;
86	}
87	
88	/* ── The quote tool ─────────────────────────────────────────────── */
89	
90	export interface QuoteTools {
91	  /** Pass to `generateText({ tools })`. */
92	  tools: ToolSet;
93	  /** The first passage the model successfully quoted, used as the anchor. */
94	  getAnchor: () => string | undefined;
95	}
96	
97	/**
98	 * Build a `quote_passage` tool bound to one draft. The execute closure records
99	 * every resolved passage so the caller can read back the anchor after
100	 * generation completes.
101	 */
102	export function buildQuoteTools(draftText: string): QuoteTools {
103	  const resolved: string[] = [];
104	
105	  const tools: ToolSet = {
106	    quote_passage: tool({
107	      description:
108	        "Look up the exact text of a passage from the writer's draft. " +
109	        "Pass the sentence (or a close approximation of it) you are " +
110	        "responding to; the tool returns the verbatim text as it appears " +
111	        "in the draft. Call this before making any claim about the draft so " +
112	        "your note pins to the real passage. Do not retype passages by hand.",
113	      inputSchema: jsonSchema<{ query: string }>({
114	        type: "object",
115	        properties: {
116	          query: {
117	            type: "string",
118	            description:
119	              "The sentence or short passage from the draft you want to quote.",
120	          },
121	        },
122	        required: ["query"],
123	        additionalProperties: false,
124	      }),
125	      execute: async ({ query }) => {
126	        const passage = resolveDraftPassage(query, draftText);
127	        if (passage) {
128	          resolved.push(passage);
129	          return { found: true, passage };
130	        }
131	        return {
132	          found: false,
133	          passage: null,
134	          note: "No matching passage found in the draft. Quote something the writer actually wrote.",
135	        };
136	      },
137	    }),
138	  };
139	
140	  return {
141	    tools,
142	    getAnchor: () => resolved[0],
143	  };
144	}
