Bun.serve({
  port: 8099,
  async fetch(req: Request) {
    const body = (await req.json()) as {
      messages: Array<{ role: string; content?: unknown }>;
    };
    const hasToolResult = body.messages.some((m) => m.role === "tool");
    const userMsg = body.messages.filter((m) => m.role === "user")[0];
    const text =
      typeof userMsg?.content === "string"
        ? userMsg.content
        : JSON.stringify(userMsg?.content ?? "");

    // The draft sits between """ fences in buildUserPrompt. Quote a real
    // sentence from it — what a competent model would do.
    const draft = text.match(/"""\n([\s\S]*?)\n"""/)?.[1] ?? text;
    const sentences = draft.match(/[^.!?\n]{25,}[.!?]/g) ?? [];
    const quote = (sentences[0] ?? "the draft").trim();

    const message = hasToolResult
      ? {
          role: "assistant",
          content:
            "<think>The writer leans on abstraction.</think>That line does the work, but stops one step short of the specific.",
        }
      : {
          role: "assistant",
          content: null,
          tool_calls: [
            {
              id: "call_1",
              type: "function",
              function: {
                name: "quote_passage",
                arguments: JSON.stringify({ query: quote }),
              },
            },
          ],
        };

    return Response.json({
      id: "chatcmpl-mock",
      object: "chat.completion",
      created: Math.floor(Date.now() / 1000),
      model: "mock-lfm",
      choices: [
        {
          index: 0,
          message,
          finish_reason: hasToolResult ? "stop" : "tool_calls",
        },
      ],
      usage: { prompt_tokens: 100, completion_tokens: 40, total_tokens: 140 },
    });
  },
});
